          const password = String(body.password || "").trim();
          if (!email || !email.includes("@")) {
            return jsonResponse({ detail: "Vui l\xF2ng nh\u1EADp \u0111\u1ECBa ch\u1EC9 email h\u1EE3p l\u1EC7" }, 400);
          }
